    elif base.endswith('.yaml') or base.endswith('.yml'):
        return 'yaml'
    elif base.endswith('.tbln'):
        return 'tbln'
    elif base.endswith('.at'):
        return 'at'
    elif base.endswith('.raw'):
        return 'raw'
    elif base.endswith('.vf'):
        return 'vf'
    else:
        return None

def guess_compression_from_path(out_path):
    lower = out_path.lower()
    if lower.endswith('.gz'):
        return 'gz'
    elif lower.endswith('.bz2'):
        return 'bz2'
    elif lower.endswith('.zst') or lower.endswith('.zstd'):
        return 'zstd'
    elif lower.endswith('.xz'):
        return 'xz'
    elif lower.endswith('.lz4'):
        return 'lz4'
    else:
        return None

def parse_simple_yaml(text):
    lines = text.splitlines()
    result = []
    current = None
    for line in lines:
        stripped = line.lstrip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped.startswith('-'):
            if current is not None:
                result.append(current)
            current = {}
            rest = stripped[1:].strip()
            if rest and ':' in rest:
                k,v = rest.split(':',1)
                current[k.strip()] = v.strip().strip('"\'')
            continue
        else:
            if ':' in stripped:
                k,v = stripped.split(':',1)
                k=k.strip()
                v=v.strip().strip('"\'')
                if current is None:
                    current={}
                current[k]=v
    if current is not None:
        result.append(current)
    return result

def parse_tbln(text):
    lines = text.splitlines()
    names = None
    types = None
    rows = []
    for line in lines:
        stripped=line.strip()
        if not stripped:
            continue
        if stripped.startswith(';'):
            lower = stripped.lower()
            if 'name:' in lower:
                after = stripped.split('name:',1)[1]
                parts = after.split('|')
                names = [p.strip() for p in parts if p.strip()!='']
            elif 'type:' in lower:
                after = stripped.split('type:',1)[1]
                parts = after.split('|')
                types = [p.strip() for p in parts if p.strip()!='']
        else:
            if stripped.startswith('|'):
                raw = stripped.split('|')
                raw = raw[1:-1]
                vals = [p.strip() for p in raw]
                rows.append(vals)
    return names, types, rows

def simple_jq(data, expr):
    if not expr:
        return data
    expr = expr.strip()
    if not expr:
        return data
    if expr.startswith('.'):
        expr = expr[1:]
    if not expr:
        return data
    parts = expr.split('.')
    cur = data
    for part in parts:
        if not part:
            continue
        if part.endswith('[]'):
            field = part[:-2]
            if field:
                if isinstance(cur, dict):
                    cur = cur.get(field)
                elif isinstance(cur, list):
                    new = []
                    for el in cur:
                        if isinstance(el, dict):
                            v = el.get(field)
                            if v is not None:
                                new.append(v)
                        elif isinstance(el, list):
                            # if already list?
                            pass
                    # flatten if first element is list?
                    if new and isinstance(new[0], list):
                        flat=[]
                        for sub in new:
                            if isinstance(sub, list):
                                flat.extend(sub)
                            else:
                                flat.append(sub)
                        cur = flat
                    else:
                        cur = new
                else:
                    cur = None
            else:
                # []
                pass
            continue
        else:
            if part == "[]":
                continue
            if isinstance(cur, list):
                new_list = []
                for el in cur:
                    if isinstance(el, dict):
                        new_list.append(el.get(part))
                    else:
                        new_list.append(None)
                cur = new_list
            elif isinstance(cur, dict):
                cur = cur.get(part)
            else:
                cur = None
        if cur is None:
            break
    return cur

def read_input_file(original_identifier, input_opts):
    file_part = original_identifier.split('::')[0] if '::' in original_identifier else original_identifier
    jq_from_table = original_identifier.split('::',1)[1] if '::' in original_identifier else None
    effective_jq = jq_from_table if jq_from_table is not None else input_opts.get('ijq')

    fmt_override = input_opts.get('format_override')
    if fmt_override:
        fmt = fmt_override
    else:
        fmt = guess_input_format(original_identifier)

    delim = input_opts.get('id', ',')
    if fmt == 'tsv' and input_opts.get('id') is None:
        delim = '\t'

    ih = input_opts.get('ih', False)
    inum = input_opts.get('inum', False)
    is_skip = input_opts.get('is', 0)
    ilr = input_opts.get('ilr', 0)
    inull = input_opts.get('inull', None)

    # read content
    if file_part == '-':
        content = sys.stdin.read()
    else:
        if not os.path.exists(file_part):
            raise FileNotFoundError(file_part)
        with open(file_part, 'r', encoding='utf-8', newline='') as f:
            content = f.read()

    cols = []
    rows = []
    types = []

    if fmt in ('csv','tsv'):
        lines = content.splitlines()
        if is_skip:
            lines = lines[is_skip:]
        if not lines:
            return [], [], [], file_part, effective_jq
        reader = csv.reader(lines, delimiter=delim)
        all_rows = list(reader)
        if not all_rows:
            return [], [], [], file_part, effective_jq
        if ih:
            columns = all_rows[0]
            data_rows = all_rows[1:]
        else:
            max_cols = max(len(r) for r in all_rows) if all_rows else 0
            columns = [f'c{i+1}' for i in range(max_cols)]
            data_rows = all_rows
        if ilr and ilr>0:
            data_rows = data_rows[:ilr]
        result=[]
        idx=0
        for r in data_rows:
            idx+=1
            if len(r) < len(columns):
                r = r + ['']*(len(columns)-len(r))
            elif len(r) > len(columns):
                r = r[:len(columns)]
            d={}
            for col,val in zip(columns, r):
                if inull is not None and val == inull:
                    d[col]=None
                else:
                    d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns = ['num']+columns
        cols = columns
        rows = result
        types = ['text']*len(cols)

    elif fmt == 'ltsv':
        lines = content.splitlines()
        if is_skip:
            lines = lines[is_skip:]
        first=None
        for line in lines:
            if line.strip():
                first=line
                break
        if first is None:
            return [], [], [], file_part, effective_jq
        parts = first.split('\t')
        columns=[]
        for p in parts:
            if ':' in p:
                k = p.split(':',1)[0]
                if k and k not in columns:
                    columns.append(k)
        result=[]
        idx=0
        for line in lines:
            if not line.strip():
                continue
            idx+=1
            if ilr and idx>ilr:
                break
            mapping={}
            for field in line.split('\t'):
                if ':' not in field:
                    continue
                k,v = field.split(':',1)
                mapping[k]=v
            d={}
            for col in columns:
                v = mapping.get(col,'')
                if inull is not None and v==inull:
                    d[col]=None
                else:
                    d[col]=v
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)

    elif fmt == 'json':
        data=None
        if not content.strip():
            data=[]
        else:
            try:
                data=json.loads(content)
            except:
                # try jsonl
                items=[]
                for line in content.splitlines():
                    line=line.strip()
                    if not line:
                        continue
                    try:
                        items.append(json.loads(line))
                    except:
                        continue
                data=items
        if effective_jq:
            data = simple_jq(data, effective_jq)
        if isinstance(data, dict):
            list_data=[data]
        elif isinstance(data, list):
            list_data=data
        else:
            list_data=[]
        all_keys=[]
        for item in list_data:
            if isinstance(item, dict):
                for k in item.keys():
                    if k not in all_keys:
                        all_keys.append(k)
        columns=all_keys
        if is_skip:
            list_data=list_data[is_skip:]
        if ilr and ilr>0:
            list_data=list_data[:ilr]
        result=[]
        idx=0
        for item in list_data:
            if not isinstance(item, dict):
                continue
            idx+=1
            d={}
            for col in columns:
                v=item.get(col)
                if inull is not None and isinstance(v,str) and v==inull:
                    d[col]=None
                else:
                    if v is None:
                        d[col]=None
                    elif isinstance(v, bool):
                        d[col]=str(v).lower() if False else str(v)
                        # Actually for json, boolean? Original converts to "true"/"false"? We saw string "1" for int. For bool, maybe string? We'll keep as string
                        d[col]=str(v) if not isinstance(v,str) else v
                        # But for simplicity keep string
                    elif isinstance(v, (dict,list)):
                        # Keep nested as is? For output json, we want to output as is? But original flattened nested? Let's keep as json string? Actually we will keep as is and handle output
                        # For now, if v is dict/list, keep as is
                        # But for csv output, we need string representation
                        d[col]=v
                        # For numeric conversion, convert numbers to string
                        if isinstance(v, (int,float)) and not isinstance(v,bool):
                            d[col]=str(v)
                    else:
                        if isinstance(v, (int,float)):
                            d[col]=str(v)
                        else:
                            d[col]=v if isinstance(v,str) else str(v)
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)

    elif fmt == 'yaml':
        data=parse_simple_yaml(content)
        all_keys=[]
        for item in data:
            for k in item.keys():
                if k not in all_keys:
                    all_keys.append(k)
        columns=all_keys
        if is_skip:
            data=data[is_skip:]
        if ilr and ilr>0:
            data=data[:ilr]
        result=[]
        idx=0
        for item in data:
            idx+=1
            d={}
            for col in columns:
                v=item.get(col,'')
                if inull is not None and v==inull:
                    d[col]=None
                else:
                    d[col]=v
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(columns)

    elif fmt == 'tbln':
        names,tbl_types,tbl_rows=parse_tbln(content)
        if not names:
            return [], [], [], file_part, effective_jq
        columns=names
        types=tbl_types if tbl_types else ['text']*len(columns)
        if is_skip:
            tbl_rows=tbl_rows[is_skip:]
        if ilr and ilr>0:
            tbl_rows=tbl_rows[:ilr]
        result=[]
        idx=0
        for r in tbl_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val,typ in zip(columns, r, types):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    if typ in ('int','integer'):
                        try:
                            d[col]=int(val) if val!='' else None
                        except:
                            d[col]=val
                    elif typ in ('real','float','double','numeric','number'):
                        try:
                            # try int if no dot?
                            if val=='':
                                d[col]=None
                            else:
                                # if contains dot, float
                                if '.' in val:
                                    d[col]=float(val)
                                else:
                                    try:
                                        d[col]=int(val)
                                    except:
                                        d[col]=float(val)
                        except:
                            d[col]=val
                    else:
                        d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
            types=['int']+types
        cols=columns
        rows=result
        # types already

    elif fmt == 'text':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        if ilr and ilr>0:
            lines=lines[:ilr]
        columns=['text']
        result=[]
        idx=0
        for line in lines:
            idx+=1
            v=line
            if inull is not None and v==inull:
                d={'text': None}
            else:
                d={'text': v}
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num','text']
        cols=columns
        rows=result
        types=['text']*len(cols)

    elif fmt == 'width':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        tokenized=[re.split(r'\s+', line.strip()) for line in lines if line.strip()]
        if not tokenized:
            return [], [], [], file_part, effective_jq
        if ih:
            columns=tokenized[0]
            data_rows=tokenized[1:]
        else:
            columns=tokenized[0]
            data_rows=tokenized[1:]
        if ilr and ilr>0:
            data_rows=data_rows[:ilr]
        result=[]
        idx=0
        for r in data_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val in zip(columns, r):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)

    else:
        cols=[]
        rows=[]
        types=[]

    return cols, rows, types, file_part, effective_jq

def extract_table_identifiers(sql):
    # Find table names after FROM and JOIN
    # This is simplistic: token after FROM or JOIN, up to next keyword or punctuation
    # Pattern: (?:FROM|JOIN)\s+([`"\[]?[^`\s,;()\[\]"]+[`"\]]?|\S+)
    # But we need to handle file paths with slashes, colons, etc.
    # We'll use regex that captures non-space, non-comma, non-semicolon, stops before alias keywords
    # Actually we can parse by splitting? Let's use regex: r'\b(?:FROM|JOIN)\b\s+([^\s,;()]+)'
    # Then for each match, strip surrounding quotes/backticks/brackets
    pattern = re.compile(r'\b(?:FROM|JOIN)\b\s+([^\s,;()]+)', re.IGNORECASE)
    matches = pattern.findall(sql)
    # Clean each: remove surrounding ` " ' [ ]
    cleaned=[]
    for m in matches:
        # Remove possible trailing alias? Actually after FROM, could be "table AS alias", our pattern stops before space, so captures table only
        # Strip quotes
        t = m.strip()
        # Remove backticks, double quotes, single quotes, square brackets
        t = t.strip('`"[]')
        # Also need to handle that table may be like "/tmp/a.csv" with quotes? Already stripped
        # Remove possible :: part? Keep :: for jq handling, so keep whole
        # Also remove trailing parentheses?
        t = t.rstrip(',;')
        cleaned.append(t)
    return cleaned

def convert_rows_to_sqlite_table(conn, table_name, columns, rows, types):
    # Create table
    # Sanitize column names for sqlite: need to quote with "
    # For types: use TEXT unless int/real from tbln
    # Drop if exists
    cur = conn.cursor()
    # Drop
    try:
        cur.execute(f'DROP TABLE IF EXISTS "{table_name}"')
    except:
        pass
    # Build create
    col_defs=[]
    for col, typ in zip(columns, types if len(types)==len(columns) else ['text']*len(columns)):
        # Map typ
        if typ in ('int','integer'):
            sql_type='INTEGER'
        elif typ in ('real','float','double','numeric','number'):
            sql_type='REAL'
        else:
            sql_type='TEXT'
        # Escape col name double quotes
        col_esc = col.replace('"','""')
        col_defs.append(f'"{col_esc}" {sql_type}')
    if not col_defs:
        # No columns, create with one dummy?
        return
    create_sql = f'CREATE TEMPORARY TABLE "{table_name}" ({", ".join(col_defs)})'
    cur.execute(create_sql)
    # Insert rows
    if rows:
        placeholders = ",".join(["?"]*len(columns))
        col_list = ",".join([f'"{c.replace(chr(34), chr(34)+chr(34))}"' for c in columns])
        insert_sql = f'INSERT INTO "{table_name}" ({col_list}) VALUES ({placeholders})'
        data=[]
        for r in rows:
            vals=[]
            for col in columns:
                v=r.get(col)
                # Convert to appropriate type? Keep as is, sqlite will handle
                vals.append(v)
            data.append(tuple(vals))
        cur.executemany(insert_sql, data)
    conn.commit()

def format_output(columns, result_rows, output_format, output_opts, out_file=None):
    # result_rows is list of sqlite3.Row or tuples? We'll convert to list of dicts
    # columns: list of column names from cursor description
    # output_opts: od, oq, oaq, oh, onowrap, onull, ocrlf
    od = output_opts.get('od', ',')
    oq = output_opts.get('oq', '"')
    oaq = output_opts.get('oaq', False)
    oh = output_opts.get('oh', False)
    onowrap = output_opts.get('onowrap', False)
    onull = output_opts.get('onull', None)
    ocrlf = output_opts.get('ocrlf', False)
    line_ending = '\r\n' if ocrlf else '\n'

    # Convert result_rows which are sqlite Row objects to list of dicts or list of lists?
    # For formatting, we need to handle None -> onull or empty?
    # For csv etc, we need to output strings.

    # Helper to convert value for output: None -> onull if set else ""? For json, None -> null, for csv, None -> onull if set else ""? Let's check earlier:
    # For -inull "" -ojson with null, json output had null.
    # For -inull "" -onull "NULL" -ojson, json output had "NULL" string.
    # For -inull "" -ocsv, csv output had empty? Actually test: echo -e "a,b\n1,\n2,foo" with -inull "" -ocsv gave "1,\n2,foo" -> first row second col empty. With -onull "NULL" -> "1,NULL"
    # So for csv, None -> onull if set else "".

    def val_to_str(v):
        if v is None:
            return onull if onull is not None else ""
        # For bool? Convert to string
        if isinstance(v, bytes):
            return v.decode()
        return str(v)

    # For json, we need to preserve None as None, but convert other types? For csv input, all values are strings, so json output should be strings? But for tbln int types, json output had numbers (1 not "1").
    # Our result_rows from sqlite may have ints for tbln etc. So for json we should keep types.

    output = ""

    if output_format == 'csv':
        # Use csv writer
        sio = io.StringIO()
        writer = csv.writer(sio, delimiter=od, quotechar=oq, quoting=csv.QUOTE_MINIMAL if not oaq else csv.QUOTE_ALL, lineterminator=line_ending)
        # But need to handle -oq custom quote char, and -oaq
        # For -od, delimiter
        # For -oh, output header
        if oh:
            writer.writerow(columns)
        for row in result_rows:
            # row is tuple
            out_row = []
            for v in row:
                if v is None:
                    out_row.append(onull if onull is not None else "")
                else:
                    out_row.append(v)
            writer.writerow(out_row)
        output = sio.getvalue()

    elif output_format == 'json':
        # Build list of dicts
        list_out=[]
        for row in result_rows:
            d={}
            for col, v in zip(columns, row):
                if v is None:
                    # If onull set, replace None with onull string? Earlier test: -inull "" -onull "NULL" -ojson gave "NULL" string for null. So onull replaces null with string in json output.
                    if onull is not None:
                        d[col]=onull
                    else:
                        d[col]=None
                else:
                    d[col]=v
            list_out.append(d)
        output = json.dumps(list_out, indent=2)
        output += "\n"  # add newline?

    elif output_format == 'jsonl':
        lines=[]
        for row in result_rows:
            d={}
            for col,v in zip(columns, row):
                if v is None:
                    if onull is not None:
                        d[col]=onull
                    else:
                        d[col]=None
                else:
                    d[col]=v
            lines.append(json.dumps(d))
        output = line_ending.join(lines)
        if lines:
            output += line_ending

    elif output_format == 'ltsv':
        lines=[]
        for row in result_rows:
            parts=[]
            for col,v in zip(columns, row):
                if v is None:
                    vs = onull if onull is not None else ""
                else:
                    vs = str(v)
                parts.append(f"{col}:{vs}")
            lines.append("\t".join(parts))
        output = line_ending.join(lines)
        if lines:
            output += line_ending

    elif output_format == 'raw':
        # Raw: output first column? Or all columns joined by od? Let's check earlier: -oraw with -od " | " gave "1 | 2"
        # For raw, they output rows as delimited by od? Let's test: For csv with 2 columns, -oraw -od " - " gave "1 - Orange"
        # So raw outputs all columns joined by od, similar to csv but without quoting?
        # And if -oh, header? Probably not needed
        lines=[]
        for row in result_rows:
            # join values with od
            vals=[]
            for v in row:
                if v is None:
                    vs = onull if onull is not None else ""
                else:
                    vs = str(v)
                vals.append(vs)
            lines.append(od.join(vals))
        output = line_ending.join(lines)
        if lines:
            output += line_ending

    elif output_format == 'tbln':
        # ; name: | col1 | col2 |
        # ; type: | type1 | type2 |
        # | val1 | val2 |
        # Types: need to infer from data? For text columns, type text, for int etc?
        # Our result from sqlite: we can attempt to infer types from column values? But original tbln output for csv gave all text types.
        # For tbln input that had types int,text, output gave int and numeric? Actually earlier we saw tbln conversion: input tbln with int,text gave output ; type: | int | text |, but when converting csv to tbln, types were text.
        # For simplicity, infer types: if all values in column are int, type int, elif float, real, else text. But for original csv->tbln, all text.
        # We'll infer.

        # Determine types
        inferred_types=[]
        # Transpose rows to columns
        if result_rows:
            for col_idx, col_name in enumerate(columns):
                col_vals = [row[col_idx] for row in result_rows]
                # check if all int?
                is_int=True
                is_real=True
                for v in col_vals:
                    if v is None or v=='':
                        continue
                    try:
                        int(str(v))
                    except:
                        is_int=False
                    try:
                        float(str(v))
                    except:
                        is_real=False
                if is_int:
                    inferred_types.append('int')
                elif is_real:
                    inferred_types.append('numeric')
                else:
                    inferred_types.append('text')
        else:
            inferred_types=['text']*len(columns)

        # Build output
        # ; name: | col1 | col2 |
        # Escape col names?
        name_line = "; name: | " + " | ".join(columns) + " |"
        type_line = "; type: | " + " | ".join(inferred_types) + " |"
        lines=[name_line, type_line]
        for row in result_rows:
            vals=[]
            for v in row:
                if v is None:
                    vs = onull if onull is not None else ""
                else:
                    vs = str(v)
                vals.append(vs)
            lines.append("| " + " | ".join(vals) + " |")
        output = line_ending.join(lines)
        if lines:
            output += line_ending

    elif output_format == 'at' or output_format == 'md':
        # ASCII Table or Markdown
        # Need to compute column widths
        # Columns: headers are column names
        # Rows: list of string representations
        # For at, border with +---+ etc, header centered, data: numeric right, text left? Let's implement simplified: header centered, data left for text, right for numeric?
