ALL_FLAGS = set(BOOL_FLAGS.keys()) | set(STRING_FLAGS.keys())

def parse_bool_value(v):
    if v is None:
        return True
    lv = v.lower()
    if lv in ("true","t","1",""):
        return True
    if lv in ("false","f","0"):
        return False
    # if not recognized, treat as true? but for simplicity
    return True

def print_help():
    sys.stderr.write(HELP_TEXT+"\n")

def print_version():
