def error_flag_undefined(flag_str):
    # flag_str is like "-o" or "-unknown"
    sys.stderr.write(f"flag provided but not defined: {flag_str}\n")
    sys.stderr.write(HELP_TEXT+"\n")
    sys.exit(2)

def error_flag_needs_arg(flag_str):
    sys.stderr.write(f"flag needs an argument: {flag_str}\n")
    sys.stderr.write(HELP_TEXT+"\n")
    sys.exit(2)

def parse_args(argv):
    # returns parsed dict and positional list (SQL parts)
    parsed = {}
    # set defaults
    for k,v in BOOL_FLAGS.items():
        parsed[k]=v
    for k,v in STRING_FLAGS.items():
        parsed[k]=v

    positional = []
    i=0
    # For Go flag behavior, after first positional, rest are positional
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            positional.extend(argv[i+1:])
            break
        if not arg.startswith("-") or arg == "-":
            # positional starts
            positional = argv[i:]
            break
        # flag
        stripped = arg.lstrip("-")
        if stripped == "":
            # arg is just "-" or "--"? "-" already handled, "--" handled
            positional = argv[i:]
            break
        if "=" in stripped:
            name, val = stripped.split("=",1)
            # name is flag name
            # check if defined
            if name not in ALL_FLAGS:
                # try to see if name starts with known? But our mapping exact
                # For -ojson=false, name is "ojson", val "false" -> should be bool
                # For -t=/tmp/file, name "t", val "/tmp/file"
                # So check
                error_flag_undefined(f"-{name}")
            if name in BOOL_FLAGS:
                # bool with value
                # If val is "true"/"false", parse
                b = parse_bool_value(val)
                parsed[name]=b
            else:
                # string flag
                parsed[name]=val
            i+=1
            continue
        else:
            name = stripped
            if name not in ALL_FLAGS:
                error_flag_undefined(f"-{name}")
            if name in BOOL_FLAGS:
                parsed[name]=True
                i+=1
                continue
            else:
                # string flag needs next arg
                if i+1 >= len(argv):
                    error_flag_needs_arg(f"-{name}")
                nxt = argv[i+1]
                # If next arg looks like flag and also not "-" (stdin marker), but Go would still consume it as value? Actually for string flags, Go consumes next arg even if it looks like flag? Let's test: ./executable -t -ojson "SELECT..." -> -t value "-ojson"? We saw earlier -t -ojson -ojson gave error near "-": syntax error SELECT * FROM -ojson, meaning -t consumed "-ojson" as its value. So string flags DO consume next arg even if it looks like a flag.
                # So we always consume next arg as value
                parsed[name]=nxt
                i+=2
                continue
    return parsed, positional

# Input format guessing etc
def guess_input_format(path):
    if not path:
        return 'csv'
    if '::' in path:
        file_part = path.split('::')[0]
    else:
        file_part = path
    if file_part == '-' or file_part == '':
        return 'csv'
    lower = file_part.lower()
    if lower.endswith('.ltsv'):
        return 'ltsv'
    elif lower.endswith('.tsv') or lower.endswith('.tab'):
        return 'tsv'
    elif lower.endswith('.csv'):
        return 'csv'
    elif lower.endswith('.json') or lower.endswith('.jsonl'):
        return 'json'
    elif lower.endswith('.yaml') or lower.endswith('.yml'):
        return 'yaml'
    elif lower.endswith('.tbln'):
        return 'tbln'
    elif lower.endswith('.width'):
        return 'width'
    elif lower.endswith('.txt'):
        return 'csv'
    else:
        # Use suffix
        ext = pathlib.Path(file_part).suffix.lower()
        if ext == '.ltsv':
            return 'ltsv'
        elif ext == '.tsv':
            return 'tsv'
        elif ext in ('.json','.jsonl'):
            return 'json'
        elif ext in ('.yaml','.yml'):
            return 'yaml'
        elif ext == '.tbln':
            return 'tbln'
        elif ext == '.width':
            return 'width'
        else:
            return 'csv'

def guess_output_format_from_path(out_path):
    lower = out_path.lower()
    comp_suffixes = ['.gz','.bz2','.zst','.xz','.lz4','.zstd']
    base = lower
    for suf in comp_suffixes:
        if base.endswith(suf):
            base = base[:-len(suf)]
            break
    if base.endswith('.json'):
        return 'json'
    elif base.endswith('.jsonl'):
        return 'jsonl'
    elif base.endswith('.ltsv'):
        return 'ltsv'
    elif base.endswith('.csv') or base.endswith('.tsv'):
        return 'csv'
    elif base.endswith('.md'):
        return 'md'
    elif base.endswith('.yaml') or base.endswith('.yml'):
        return 'yaml'
    elif base.endswith('.tbln'):
        return 'tbln'
    elif base.endswith('.at'):
        return 'at'
    elif base.endswith('.raw'):
        return 'raw'
    elif base.endswith('.vf'):
        return 'vf'
    else:
        return None

def guess_compression_from_path(out_path):
    lower = out_path.lower()
    if lower.endswith('.gz'):
        return 'gz'
    elif lower.endswith('.bz2'):
        return 'bz2'
    elif lower.endswith('.zst') or lower.endswith('.zstd'):
        return 'zstd'
    elif lower.endswith('.xz'):
        return 'xz'
    elif lower.endswith('.lz4'):
        return 'lz4'
    else:
        return None

def parse_simple_yaml(text):
    lines = text.splitlines()
    result = []
    current = None
    for line in lines:
        stripped = line.lstrip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped.startswith('-'):
            if current is not None:
                result.append(current)
            current = {}
            rest = stripped[1:].strip()
            if rest and ':' in rest:
                k,v = rest.split(':',1)
                current[k.strip()] = v.strip().strip('"\'')
            continue
        else:
            if ':' in stripped:
                k,v = stripped.split(':',1)
                k=k.strip()
                v=v.strip().strip('"\'')
                if current is None:
                    current={}
                current[k]=v
    if current is not None:
        result.append(current)
    return result

def parse_tbln(text):
    lines = text.splitlines()
    names = None
    types = None
    rows = []
    for line in lines:
        stripped=line.strip()
        if not stripped:
            continue
        if stripped.startswith(';'):
            lower = stripped.lower()
            if 'name:' in lower:
                after = stripped.split('name:',1)[1]
                parts = after.split('|')
                names = [p.strip() for p in parts if p.strip()!='']
            elif 'type:' in lower:
                after = stripped.split('type:',1)[1]
                parts = after.split('|')
                types = [p.strip() for p in parts if p.strip()!='']
        else:
            if stripped.startswith('|'):
                raw = stripped.split('|')
                raw = raw[1:-1]
                vals = [p.strip() for p in raw]
                rows.append(vals)
    return names, types, rows

def simple_jq(data, expr):
    if not expr:
        return data
    expr = expr.strip()
    if not expr:
        return data
    if expr.startswith('.'):
        expr = expr[1:]
    if not expr:
        return data
    parts = expr.split('.')
    cur = data
    for part in parts:
        if not part:
            continue
        if part.endswith('[]'):
            field = part[:-2]
            if field:
                if isinstance(cur, dict):
                    cur = cur.get(field)
                elif isinstance(cur, list):
                    new = []
                    for el in cur:
                        if isinstance(el, dict):
                            v = el.get(field)
                            if v is not None:
                                new.append(v)
                        elif isinstance(el, list):
                            # if already list?
                            pass
                    # flatten if first element is list?
                    if new and isinstance(new[0], list):
                        flat=[]
                        for sub in new:
                            if isinstance(sub, list):
                                flat.extend(sub)
                            else:
                                flat.append(sub)
                        cur = flat
                    else:
                        cur = new
                else:
                    cur = None
            else:
                # []
                pass
            continue
        else:
            if part == "[]":
                continue
            if isinstance(cur, list):
                new_list = []
                for el in cur:
                    if isinstance(el, dict):
                        new_list.append(el.get(part))
                    else:
                        new_list.append(None)
                cur = new_list
            elif isinstance(cur, dict):
                cur = cur.get(part)
            else:
                cur = None
        if cur is None:
            break
    return cur

def read_input_file(original_identifier, input_opts):
    file_part = original_identifier.split('::')[0] if '::' in original_identifier else original_identifier
    jq_from_table = original_identifier.split('::',1)[1] if '::' in original_identifier else None
    effective_jq = jq_from_table if jq_from_table is not None else input_opts.get('ijq')

    fmt_override = input_opts.get('format_override')
    if fmt_override:
