                    elif isinstance(v, bool):
                        d[col]=str(v).lower() if False else str(v)
                        # Actually for json, boolean? Original converts to "true"/"false"? We saw string "1" for int. For bool, maybe string? We'll keep as string
                        d[col]=str(v) if not isinstance(v,str) else v
                        # But for simplicity keep string
                    elif isinstance(v, (dict,list)):
                        # Keep nested as is? For output json, we want to output as is? But original flattened nested? Let's keep as json string? Actually we will keep as is and handle output
                        # For now, if v is dict/list, keep as is
                        # But for csv output, we need string representation
                        d[col]=v
                        # For numeric conversion, convert numbers to string
                        if isinstance(v, (int,float)) and not isinstance(v,bool):
                            d[col]=str(v)
                    else:
                        if isinstance(v, (int,float)):
