            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)

    elif fmt == 'yaml':
        data=parse_simple_yaml(content)
