def extract_table_identifiers(sql):
    # Find table names after FROM and JOIN
    # This is simplistic: token after FROM or JOIN, up to next keyword or punctuation
    # Pattern: (?:FROM|JOIN)\s+([`"\[]?[^`\s,;()\[\]"]+[`"\]]?|\S+)
    # But we need to handle file paths with slashes, colons, etc.
    # We'll use regex that captures non-space, non-comma, non-semicolon, stops before alias keywords
    # Actually we can parse by splitting? Let's use regex: r'\b(?:FROM|JOIN)\b\s+([^\s,;()]+)'
    # Then for each match, strip surrounding quotes/backticks/brackets
    pattern = re.compile(r'\b(?:FROM|JOIN)\b\s+([^\s,;()]+)', re.IGNORECASE)
    matches = pattern.findall(sql)
    # Clean each: remove surrounding ` " ' [ ]
    cleaned=[]
    for m in matches:
        # Remove possible trailing alias? Actually after FROM, could be "table AS alias", our pattern stops before space, so captures table only
        # Strip quotes
        t = m.strip()
        # Remove backticks, double quotes, single quotes, square brackets
        t = t.strip('`"[]')
        # Also need to handle that table may be like "/tmp/a.csv" with quotes? Already stripped
        # Remove possible :: part? Keep :: for jq handling, so keep whole
        # Also remove trailing parentheses?
        t = t.rstrip(',;')
        cleaned.append(t)
    return cleaned

def convert_rows_to_sqlite_table(conn, table_name, columns, rows, types):
    # Create table
    # Sanitize column names for sqlite: need to quote with "
    # For types: use TEXT unless int/real from tbln
    # Drop if exists
    cur = conn.cursor()
    # Drop
    try:
        cur.execute(f'DROP TABLE IF EXISTS "{table_name}"')
    except:
        pass
    # Build create
    col_defs=[]
    for col, typ in zip(columns, types if len(types)==len(columns) else ['text']*len(columns)):
        # Map typ
        if typ in ('int','integer'):
            sql_type='INTEGER'
        elif typ in ('real','float','double','numeric','number'):
            sql_type='REAL'
        else:
            sql_type='TEXT'
        # Escape col name double quotes
        col_esc = col.replace('"','""')
        col_defs.append(f'"{col_esc}" {sql_type}')
    if not col_defs:
        # No columns, create with one dummy?
        return
    create_sql = f'CREATE TEMPORARY TABLE "{table_name}" ({", ".join(col_defs)})'
    cur.execute(create_sql)
    # Insert rows
    if rows:
        placeholders = ",".join(["?"]*len(columns))
        col_list = ",".join([f'"{c.replace(chr(34), chr(34)+chr(34))}"' for c in columns])
        insert_sql = f'INSERT INTO "{table_name}" ({col_list}) VALUES ({placeholders})'
        data=[]
        for r in rows:
            vals=[]
            for col in columns:
                v=r.get(col)
                # Convert to appropriate type? Keep as is, sqlite will handle
                vals.append(v)
            data.append(tuple(vals))
        cur.executemany(insert_sql, data)
    conn.commit()

