    elif lower.endswith('.json') or lower.endswith('.jsonl'):
        return 'json'
    elif lower.endswith('.yaml') or lower.endswith('.yml'):
        return 'yaml'
    elif lower.endswith('.tbln'):
        return 'tbln'
    elif lower.endswith('.width'):
        return 'width'
    elif lower.endswith('.txt'):
        return 'csv'
    else:
        ext = pathlib.Path(file_part).suffix.lower()
        if ext == '.ltsv':
            return 'ltsv'
        elif ext == '.tsv':
            return 'tsv'
        elif ext in ('.json','.jsonl'):
            return 'json'
        elif ext in ('.yaml','.yml'):
            return 'yaml'
        elif ext == '.tbln':
            return 'tbln'
        elif ext == '.width':
            return 'width'
        else:
            return 'csv'

def guess_output_format_from_path(out_path):
    lower = out_path.lower()
    comp_suffixes = ['.gz','.bz2','.zst','.xz','.lz4','.zstd']
    base=lower
    for suf in comp_suffixes:
        if base.endswith(suf):
            base=base[:-len(suf)]
            break
    if base.endswith('.json'):
        return 'json'
    elif base.endswith('.jsonl'):
        return 'jsonl'
    elif base.endswith('.ltsv'):
        return 'ltsv'
    elif base.endswith('.csv') or base.endswith('.tsv'):
        return 'csv'
    elif base.endswith('.md'):
        return 'md'
    elif base.endswith('.yaml') or base.endswith('.yml'):
        return 'yaml'
    elif base.endswith('.tbln'):
        return 'tbln'
    elif base.endswith('.at'):
        return 'at'
    elif base.endswith('.raw'):
        return 'raw'
    elif base.endswith('.vf'):
        return 'vf'
    elif base.endswith('.out') or base.endswith('.dat'):
        return None
    else:
        return None

def guess_compression_from_path(out_path):
    lower = out_path.lower()
    if lower.endswith('.gz'):
        return 'gz'
    elif lower.endswith('.bz2'):
        return 'bz2'
    elif lower.endswith('.zst') or lower.endswith('.zstd'):
        return 'zstd'
    elif lower.endswith('.xz'):
        return 'xz'
    elif lower.endswith('.lz4'):
        return 'lz4'
    else:
        return None

def parse_simple_yaml(text):
    lines=text.splitlines()
    result=[]
    current=None
    for line in lines:
        stripped=line.lstrip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped.startswith('-'):
            if current is not None:
                result.append(current)
            current={}
            rest=stripped[1:].strip()
            if rest and ':' in rest:
                k,v=rest.split(':',1)
                current[k.strip()]=v.strip().strip('"\'')
            continue
        else:
            if ':' in stripped:
                k,v=stripped.split(':',1)
                k=k.strip()
                v=v.strip().strip('"\'')
                if current is None:
                    current={}
                current[k]=v
    if current is not None:
        result.append(current)
    return result

def parse_tbln(text):
    lines=text.splitlines()
    names=None
    types=None
    rows=[]
    for line in lines:
        stripped=line.strip()
        if not stripped:
            continue
        if stripped.startswith(';'):
            lower=stripped.lower()
            if 'name:' in lower:
                after=stripped.split('name:',1)[1]
                parts=after.split('|')
                names=[p.strip() for p in parts if p.strip()!='']
            elif 'type:' in lower:
                after=stripped.split('type:',1)[1]
                parts=after.split('|')
                types=[p.strip() for p in parts if p.strip()!='']
        else:
            if stripped.startswith('|'):
                raw=stripped.split('|')
                raw=raw[1:-1]
                vals=[p.strip() for p in raw]
                rows.append(vals)
    return names, types, rows

def simple_jq(data, expr):
    if not expr:
        return data
    expr=expr.strip()
    if not expr:
        return data
    if expr.startswith('.'):
        expr=expr[1:]
    if not expr:
        return data
    parts=expr.split('.')
    cur=data
    for part in parts:
        if not part:
            continue
        if part.endswith('[]'):
            field=part[:-2]
            if field:
                if isinstance(cur, dict):
                    cur=cur.get(field)
                elif isinstance(cur, list):
                    new=[]
                    for el in cur:
                        if isinstance(el, dict):
                            v=el.get(field)
                            if v is not None:
                                new.append(v)
                    if new and isinstance(new[0], list):
                        flat=[]
                        for sub in new:
                            if isinstance(sub, list):
                                flat.extend(sub)
                            else:
                                flat.append(sub)
                        cur=flat
                    else:
                        cur=new
                else:
                    cur=None
            continue
        else:
            if part=="[]":
                continue
            if isinstance(cur, list):
                new_list=[]
                for el in cur:
                    if isinstance(el, dict):
                        new_list.append(el.get(part))
                    else:
                        new_list.append(None)
                cur=new_list
            elif isinstance(cur, dict):
                cur=cur.get(part)
            else:
                cur=None
        if cur is None:
            break
    return cur

def read_input_file(original_identifier, input_opts):
    file_part = original_identifier.split('::')[0] if '::' in original_identifier else original_identifier
    jq_from_table = original_identifier.split('::',1)[1] if '::' in original_identifier else None
    effective_jq = jq_from_table if jq_from_table is not None else input_opts.get('ijq')
    fmt_override = input_opts.get('format_override')
    fmt = fmt_override if fmt_override else guess_input_format(original_identifier)
    delim = input_opts.get('id')
    if delim is None:
        delim = '\t' if fmt=='tsv' else ','
    ih = input_opts.get('ih', False)
    inum = input_opts.get('inum', False)
    is_skip = input_opts.get('is', 0)
    ilr = input_opts.get('ilr', 0)
    inull = input_opts.get('inull', None)
    if file_part == '-':
        content = sys.stdin.read()
    else:
        if not os.path.exists(file_part):
            raise FileNotFoundError(file_part)
        with open(file_part, 'r', encoding='utf-8', newline='') as f:
            content=f.read()
    cols=[]
    rows=[]
    types=[]
    if fmt in ('csv','tsv'):
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        if not lines:
            return [], [], [], file_part, effective_jq
        reader=csv.reader(lines, delimiter=delim)
        all_rows=list(reader)
        if not all_rows:
            return [], [], [], file_part, effective_jq
        if ih:
            columns=all_rows[0]
            data_rows=all_rows[1:]
        else:
            max_cols=max(len(r) for r in all_rows) if all_rows else 0
            columns=[f'c{i+1}' for i in range(max_cols)]
            data_rows=all_rows
        if ilr and ilr>0:
            data_rows=data_rows[:ilr]
        result=[]
        idx=0
        for r in data_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val in zip(columns, r):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='ltsv':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        first=None
        for line in lines:
            if line.strip():
                first=line
                break
        if first is None:
            return [], [], [], file_part, effective_jq
        parts=first.split('\t')
        columns=[]
        for p in parts:
            if ':' in p:
                k=p.split(':',1)[0]
                if k and k not in columns:
                    columns.append(k)
        result=[]
        idx=0
        for line in lines:
            if not line.strip():
                continue
            idx+=1
            if ilr and idx>ilr:
                break
            mapping={}
            for field in line.split('\t'):
                if ':' not in field:
                    continue
                k,v=field.split(':',1)
                mapping[k]=v
            d={}
            for col in columns:
                v=mapping.get(col,'')
                if inull is not None and v==inull:
                    d[col]=None
                else:
                    d[col]=v
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='json':
        data=None
        if not content.strip():
            data=[]
        else:
            try:
                data=json.loads(content)
            except:
                items=[]
                for line in content.splitlines():
                    line=line.strip()
                    if not line:
                        continue
                    try:
                        items.append(json.loads(line))
                    except:
                        continue
                data=items
        if effective_jq:
            data=simple_jq(data, effective_jq)
        if isinstance(data, dict):
            list_data=[data]
        elif isinstance(data, list):
            list_data=data
        else:
            list_data=[]
        all_keys=[]
        for item in list_data:
            if isinstance(item, dict):
                for k in item.keys():
                    if k not in all_keys:
                        all_keys.append(k)
        columns=all_keys
        if is_skip:
            list_data=list_data[is_skip:]
        if ilr and ilr>0:
            list_data=list_data[:ilr]
        result=[]
        idx=0
        for item in list_data:
            if not isinstance(item, dict):
                continue
            idx+=1
            d={}
            for col in columns:
                v=item.get(col)
                if inull is not None and isinstance(v,str) and v==inull:
                    d[col]=None
                else:
                    if v is None:
                        d[col]=None
                    elif isinstance(v, bool):
                        d[col]=str(v)
                    elif isinstance(v, (dict,list)):
                        if isinstance(v, (int,float)) and not isinstance(v,bool):
                            d[col]=str(v)
                        else:
                            # keep dict/list as is? but convert numbers inside? For simplicity, if dict/list, convert to string unless it's simple?
                            # For nested object case, we saw they kept object? Actually for -ijq ".[]" they kept nested object. So keep as is for dict/list, but numbers as string?
                            if isinstance(v, (int,float)):
                                d[col]=str(v)
                            else:
                                d[col]=v
                    else:
                        if isinstance(v, (int,float)):
                            d[col]=str(v)
                        else:
                            d[col]=v if isinstance(v,str) else str(v)
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='yaml':
        data=parse_simple_yaml(content)
        all_keys=[]
        for item in data:
            for k in item.keys():
                if k not in all_keys:
                    all_keys.append(k)
        columns=all_keys
        if is_skip:
            data=data[is_skip:]
        if ilr and ilr>0:
            data=data[:ilr]
        result=[]
        idx=0
        for item in data:
            idx+=1
            d={}
            for col in columns:
                v=item.get(col,'')
                if inull is not None and v==inull:
                    d[col]=None
                else:
                    d[col]=v
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(columns)
    elif fmt=='tbln':
        names,tbl_types,tbl_rows=parse_tbln(content)
        if not names:
            return [], [], [], file_part, effective_jq
        columns=names
        types=tbl_types if tbl_types else ['text']*len(columns)
        if is_skip:
            tbl_rows=tbl_rows[is_skip:]
        if ilr and ilr>0:
            tbl_rows=tbl_rows[:ilr]
        result=[]
        idx=0
        for r in tbl_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val,typ in zip(columns, r, types):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    if typ in ('int','integer'):
                        try:
                            d[col]=int(val) if val!='' else None
                        except:
                            d[col]=val
                    elif typ in ('real','float','double','numeric','number'):
                        try:
                            if val=='':
                                d[col]=None
                            else:
                                if '.' in val:
                                    d[col]=float(val)
                                else:
                                    try:
                                        d[col]=int(val)
                                    except:
                                        d[col]=float(val)
                        except:
                            d[col]=val
                    else:
                        d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
            types=['int']+types
        cols=columns
        rows=result
    elif fmt=='text':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        if ilr and ilr>0:
            lines=lines[:ilr]
        columns=['text']
        result=[]
        idx=0
        for line in lines:
            idx+=1
            v=line
            if inull is not None and v==inull:
                d={'text': None}
            else:
                d={'text': v}
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num','text']
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='width':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        tokenized=[re.split(r'\s+', line.strip()) for line in lines if line.strip()]
        if not tokenized:
            return [], [], [], file_part, effective_jq
        if ih:
            columns=tokenized[0]
            data_rows=tokenized[1:]
        else:
            columns=tokenized[0]
            data_rows=tokenized[1:]
        if ilr and ilr>0:
            data_rows=data_rows[:ilr]
        result=[]
        idx=0
        for r in data_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val in zip(columns, r):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    else:
        cols=[]
        rows=[]
        types=[]
    return cols, rows, types, file_part, effective_jq

def extract_table_identifiers(sql):
    pattern=re.compile(r'\b(?:FROM|JOIN)\b\s+([^\s,;()]+)', re.IGNORECASE)
    matches=pattern.findall(sql)
    cleaned=[]
    for m in matches:
        t=m.strip().strip('`"[]')
        t=t.rstrip(',;')
        cleaned.append(t)
    return cleaned

def convert_rows_to_sqlite_table(conn, table_name, columns, rows, types):
    cur=conn.cursor()
    try:
        cur.execute(f'DROP TABLE IF EXISTS "{table_name}"')
    except:
        pass
    col_defs=[]
    for col, typ in zip(columns, types if len(types)==len(columns) else ['text']*len(columns)):
        if typ in ('int','integer'):
            sql_type='INTEGER'
        elif typ in ('real','float','double','numeric','number'):
            sql_type='REAL'
        else:
            sql_type='TEXT'
        col_esc=col.replace('"','""')
        col_defs.append(f'"{col_esc}" {sql_type}')
    if not col_defs:
        return
    create_sql=f'CREATE TEMPORARY TABLE "{table_name}" ({", ".join(col_defs)})'
    cur.execute(create_sql)
    if rows:
        placeholders=",".join(["?"]*len(columns))
        col_list=",".join([f'"{c.replace(chr(34),chr(34)+chr(34))}"' for c in columns])
        insert_sql=f'INSERT INTO "{table_name}" ({col_list}) VALUES ({placeholders})'
        data=[]
        for r in rows:
            vals=[]
            for col in columns:
                v=r.get(col)
                vals.append(v)
            data.append(tuple(vals))
        cur.executemany(insert_sql, data)
    conn.commit()

def format_output(columns, result_rows, output_format, output_opts):
    od=output_opts.get('od', ',')
    oq=output_opts.get('oq', '"')
    oaq=output_opts.get('oaq', False)
    oh=output_opts.get('oh', False)
    onowrap=output_opts.get('onowrap', False)
    onull=output_opts.get('onull', None)
    ocrlf=output_opts.get('ocrlf', False)
    line_ending='\r\n' if ocrlf else '\n'

    def val_to_str(v):
        if v is None:
            return onull if onull is not None else ""
        return str(v)

    output=""

    if output_format=='csv':
        sio=io.StringIO()
        writer=csv.writer(sio, delimiter=od, quotechar=oq, quoting=csv.QUOTE_MINIMAL if not oaq else csv.QUOTE_ALL, lineterminator=line_ending)
        if oh:
            writer.writerow(columns)
        for row in result_rows:
            out_row=[]
            for v in row:
                if v is None:
                    out_row.append(onull if onull is not None else "")
                else:
                    out_row.append(v)
            writer.writerow(out_row)
        output=sio.getvalue()

    elif output_format=='json':
        list_out=[]
        for row in result_rows:
            d={}
            for col,v in zip(columns, row):
                if v is None:
                    d[col]=onull if onull is not None else None
                else:
                    d[col]=v
            list_out.append(d)
        output=json.dumps(list_out, indent=2)+"\n"

    elif output_format=='jsonl':
        lines=[]
        for row in result_rows:
            d={}
            for col,v in zip(columns, row):
                if v is None:
                    d[col]=onull if onull is not None else None
                else:
                    d[col]=v
            lines.append(json.dumps(d))
        output=line_ending.join(lines)
        if lines:
            output+=line_ending

    elif output_format=='ltsv':
        lines=[]
        for row in result_rows:
            parts=[]
            for col,v in zip(columns, row):
                if v is None:
                    vs=onull if onull is not None else ""
                else:
                    vs=str(v)
                parts.append(f"{col}:{vs}")
            lines.append("\t".join(parts))
        output=line_ending.join(lines)
        if lines:
            output+=line_ending

    elif output_format=='raw':
        lines=[]
        for row in result_rows:
            vals=[]
            for v in row:
                if v is None:
                    vs=onull if onull is not None else ""
                else:
                    vs=str(v)
                vals.append(vs)
            lines.append(od.join(vals))
        output=line_ending.join(lines)
        if lines:
            output+=line_ending

    elif output_format=='tbln':
        inferred_types=[]
        if result_rows:
            for col_idx,col_name in enumerate(columns):
                col_vals=[row[col_idx] for row in result_rows]
                is_int=True
                is_real=True
                for v in col_vals:
                    if v is None or v=='':
                        continue
                    try:
                        int(str(v))
                    except:
                        is_int=False
                    try:
                        float(str(v))
                    except:
                        is_real=False
                if is_int:
                    inferred_types.append('int')
                elif is_real:
                    inferred_types.append('numeric')
                else:
                    inferred_types.append('text')
        else:
            inferred_types=['text']*len(columns)
        name_line="; name: | " + " | ".join(columns) + " |"
        type_line="; type: | " + " | ".join(inferred_types) + " |"
        lines=[name_line, type_line]
        for row in result_rows:
            vals=[]
            for v in row:
                if v is None:
                    vs=onull if onull is not None else ""
                else:
                    vs=str(v)
                vals.append(vs)
            lines.append("| " + " | ".join(vals) + " |")
        output=line_ending.join(lines)
        if lines:
            output+=line_ending

    elif output_format in ('at','md'):
        str_rows=[]
        for row in result_rows:
            str_row=[]
            for v in row:
                if v is None:
                    vs=onull if onull is not None else ""
                else:
                    vs=str(v)
                str_row.append(vs)
            str_rows.append(str_row)

        col_widths=[]
        for idx,col in enumerate(columns):
            max_len=len(col)
            for r in str_rows:
                if idx < len(r):
                    l=len(r[idx])
                    if l>max_len:
                        max_len=l
            col_widths.append(max_len)

        final_widths=[]
        for idx,col in enumerate(columns):
            header_len=len(col)
            max_data_len=0
            has_long=False
            for r in str_rows:
                if idx < len(r):
                    l=len(r[idx])
                    if l>max_data_len:
                        max_data_len=l
                    if l>30 and ' ' in r[idx]:
                        has_long=True
            max_len=max(header_len, max_data_len)
            if header_len>30:
                w=header_len+2
            else:
                if has_long and not onowrap:
                    w=32
                else:
                    w=max_len+2
            final_widths.append(w)

        def wrap_cell(text, width):
            max_content=30
            if len(text)<=max_content or onowrap:
                return [text]
            if ' ' not in text:
                return [text]
            words=text.split(' ')
            lines=[]
            cur=""
            for w in words:
                if not cur:
                    cur=w
                elif len(cur)+1+len(w) <= max_content:
                    cur=cur+" "+w
                else:
                    lines.append(cur)
                    cur=w
            if cur:
                lines.append(cur)
            return lines

        def format_header_cell(text,width):
            spaces=width-len(text)
            left=spaces//2
            right=spaces-left
            return " "*left+text+" "*right

        def is_numeric(s):
            if not s:
                return False
            try:
                float(s)
                return True
            except:
                return False

        if output_format=='at':
            border="+"+"+".join(["-"*w for w in final_widths])+"+"
            lines_out=[]
            lines_out.append(border)
            header_cells=[format_header_cell(col,w) for col,w in zip(columns, final_widths)]
            lines_out.append("|"+"|".join(header_cells)+"|")
            lines_out.append(border)
            for row in str_rows:
                wrapped_cells=[]
                max_lines=1
                for idx,cell in enumerate(row):
                    w=final_widths[idx]
                    if not onowrap and len(cell)>30 and ' ' in cell:
                        wrapped=wrap_cell(cell,w)
                    else:
                        wrapped=[cell]
                    wrapped_cells.append(wrapped)
                    if len(wrapped)>max_lines:
                        max_lines=len(wrapped)
                for line_idx in range(max_lines):
                    phys_cells=[]
                    for col_idx,w in enumerate(final_widths):
                        wc=wrapped_cells[col_idx]
                        if line_idx < len(wc):
                            cell_text=wc[line_idx]
                        else:
                            cell_text=""
                        if cell_text=="":
                            phys_cells.append(" "*w)
                        else:
                            if col_idx==0 and line_idx>0:
                                # For first column when other columns wrap, show empty? Actually original for wrapped row, first column (id) second physical line was blank? In earlier example, for long desc, id column second line was "    " (4 spaces). So we keep blank.
