#!/usr/bin/env python3
import sys, os, re, csv, json, sqlite3, gzip, bz2, lzma, io, pathlib

HELP_TEXT = """trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

Usage
\ttrdsql [OPTIONS] [SQL(SELECT...)]

Options:
  -A string           analyze the file but only suggest SQL.
  -a string           analyze the file and suggest SQL.
  -config string      configuration file location.
  -db string          specify db name of the setting.
  -dblist             display db information.
  -debug              debug print.
  -driver string      database driver.  [ mysql | postgres | sqlite3 | sqlite3_ext ]
  -dsn string         database driver specific data source name.
  -help               display usage information.
  -q string           read query from the specified file.
  -t string           read table name from the specified file.
  -version            display version information.

Input Formats:
  -icsv               CSV format for input.
  -ig                 guess format from extension. (default "true")
  -ijson              JSON format for input.
  -iltsv              LTSV format for input.
  -itbln              TBLN format for input.
  -itext              text format for input.
  -iwidth             width specification format for input.
  -iyaml              YAML format for input.

Input options:
  -id string          field delimiter for input. (default ",")
  -ih                 the first line is interpreted as column names(CSV only).
  -ijq string         jq expression string for input(JSON/JSONL only).
  -ilr int            limited number of rows to read. (default 0)
  -inull value        value(string) to convert to null on input.
  -inum               add row number column.
  -ir int             number of rows to preread. (default 1)
  -is int             skip header row. (default 0)

Output Formats:
  -oat                ASCII Table format for output.
  -ocsv               CSV format for output.
  -ojson              JSON format for output.
  -ojsonl             JSON lines format for output.
  -oltsv              LTSV format for output.
  -omd                Markdown format for output.
  -oraw               Raw format for output.
  -otbln              TBLN format for output.
  -ovf                Vertical format for output.
  -oyaml              YAML format for output.

Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\\r\\n' instead of '\\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"
"""

VERSION_TEXT = "trdsql version devel"

BOOL_FLAGS = {
    "dblist": False,
    "debug": False,
    "help": False,
    "version": False,
    "icsv": False,
    "ig": False,
    "ijson": False,
    "iltsv": False,
    "itbln": False,
    "itext": False,
    "iwidth": False,
    "iyaml": False,
    "ih": False,
    "inum": False,
    "oat": False,
    "ocsv": False,
    "ojson": False,
    "ojsonl": False,
    "oltsv": False,
    "omd": False,
    "oraw": False,
    "otbln": False,
    "ovf": False,
    "oyaml": False,
    "oaq": False,
    "ocrlf": False,
    "oh": False,
    "onowrap": False,
    "out-without-guess": False,
    "h": False,
}

STRING_FLAGS = {
    "A": None,
    "a": None,
    "config": None,
    "db": None,
    "driver": None,
    "dsn": None,
    "q": None,
    "t": None,
    "id": None,
    "ijq": None,
    "ilr": None,
    "inull": None,
    "ir": None,
    "is": None,
    "od": None,
    "onull": None,
    "oq": None,
    "out": None,
    "oz": None,
}

ALL_FLAGS = set(BOOL_FLAGS.keys()) | set(STRING_FLAGS.keys())

def parse_bool_value(v):
    if v is None:
        return True
    lv = v.lower()
    if lv in ("true","t","1",""):
        return True
    if lv in ("false","f","0"):
        return False
    return True

def print_help():
    sys.stderr.write(HELP_TEXT+"\n")

def print_version():
    sys.stdout.write(VERSION_TEXT+"\n")

def error_flag_undefined(flag_str):
    sys.stderr.write(f"flag provided but not defined: {flag_str}\n")
    sys.stderr.write(HELP_TEXT+"\n")
    sys.exit(2)

def error_flag_needs_arg(flag_str):
    sys.stderr.write(f"flag needs an argument: {flag_str}\n")
    sys.stderr.write(HELP_TEXT+"\n")
    sys.exit(2)

def parse_args(argv):
    parsed = {}
    for k,v in BOOL_FLAGS.items():
        parsed[k]=v
    for k,v in STRING_FLAGS.items():
        parsed[k]=v
    positional=[]
    i=0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            positional.extend(argv[i+1:])
            break
        if not arg.startswith("-") or arg == "-":
            positional = argv[i:]
            break
        stripped = arg.lstrip("-")
        if stripped == "":
            positional = argv[i:]
            break
        if "=" in stripped:
            name,val = stripped.split("=",1)
            if name not in ALL_FLAGS:
                error_flag_undefined(f"-{name}")
            if name in BOOL_FLAGS:
                parsed[name]=parse_bool_value(val)
            else:
                parsed[name]=val
            i+=1
            continue
        else:
            name=stripped
            if name not in ALL_FLAGS:
                error_flag_undefined(f"-{name}")
            if name in BOOL_FLAGS:
                parsed[name]=True
                i+=1
                continue
            else:
                if i+1 >= len(argv):
                    error_flag_needs_arg(f"-{name}")
                nxt = argv[i+1]
                parsed[name]=nxt
                i+=2
                continue
    return parsed, positional

def guess_input_format(path):
    if not path:
        return 'csv'
    if '::' in path:
        file_part = path.split('::')[0]
    else:
        file_part = path
    if file_part == '-' or file_part == '':
        return 'csv'
    lower = file_part.lower()
    if lower.endswith('.ltsv'):
        return 'ltsv'
    elif lower.endswith('.tsv') or lower.endswith('.tab'):
        return 'tsv'
    elif lower.endswith('.csv'):
        return 'csv'
    elif lower.endswith('.json') or lower.endswith('.jsonl'):
        return 'json'
    elif lower.endswith('.yaml') or lower.endswith('.yml'):
        return 'yaml'
    elif lower.endswith('.tbln'):
        return 'tbln'
    elif lower.endswith('.width'):
        return 'width'
    elif lower.endswith('.txt'):
        return 'csv'
    else:
        ext = pathlib.Path(file_part).suffix.lower()
        if ext == '.ltsv':
            return 'ltsv'
        elif ext == '.tsv':
            return 'tsv'
        elif ext in ('.json','.jsonl'):
            return 'json'
        elif ext in ('.yaml','.yml'):
            return 'yaml'
        elif ext == '.tbln':
            return 'tbln'
        elif ext == '.width':
            return 'width'
        else:
            return 'csv'

def guess_output_format_from_path(out_path):
    lower = out_path.lower()
    comp_suffixes = ['.gz','.bz2','.zst','.xz','.lz4','.zstd']
    base=lower
    for suf in comp_suffixes:
        if base.endswith(suf):
            base=base[:-len(suf)]
            break
    if base.endswith('.json'):
        return 'json'
    elif base.endswith('.jsonl'):
        return 'jsonl'
    elif base.endswith('.ltsv'):
        return 'ltsv'
    elif base.endswith('.csv') or base.endswith('.tsv'):
        return 'csv'
    elif base.endswith('.md'):
        return 'md'
    elif base.endswith('.yaml') or base.endswith('.yml'):
        return 'yaml'
    elif base.endswith('.tbln'):
        return 'tbln'
    elif base.endswith('.at'):
        return 'at'
    elif base.endswith('.raw'):
        return 'raw'
    elif base.endswith('.vf'):
        return 'vf'
    elif base.endswith('.out') or base.endswith('.dat'):
        return None
    else:
        return None

def guess_compression_from_path(out_path):
    lower = out_path.lower()
    if lower.endswith('.gz'):
        return 'gz'
    elif lower.endswith('.bz2'):
        return 'bz2'
    elif lower.endswith('.zst') or lower.endswith('.zstd'):
        return 'zstd'
    elif lower.endswith('.xz'):
        return 'xz'
    elif lower.endswith('.lz4'):
        return 'lz4'
    else:
        return None

def parse_simple_yaml(text):
    lines=text.splitlines()
    result=[]
    current=None
    for line in lines:
        stripped=line.lstrip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped.startswith('-'):
            if current is not None:
                result.append(current)
            current={}
            rest=stripped[1:].strip()
            if rest and ':' in rest:
                k,v=rest.split(':',1)
                current[k.strip()]=v.strip().strip('"\'')
            continue
        else:
            if ':' in stripped:
                k,v=stripped.split(':',1)
                k=k.strip()
                v=v.strip().strip('"\'')
                if current is None:
                    current={}
                current[k]=v
    if current is not None:
        result.append(current)
    return result

def parse_tbln(text):
    lines=text.splitlines()
    names=None
    types=None
    rows=[]
    for line in lines:
        stripped=line.strip()
        if not stripped:
            continue
        if stripped.startswith(';'):
            lower=stripped.lower()
            if 'name:' in lower:
                after=stripped.split('name:',1)[1]
                parts=after.split('|')
                names=[p.strip() for p in parts if p.strip()!='']
            elif 'type:' in lower:
                after=stripped.split('type:',1)[1]
                parts=after.split('|')
                types=[p.strip() for p in parts if p.strip()!='']
        else:
            if stripped.startswith('|'):
                raw=stripped.split('|')
                raw=raw[1:-1]
                vals=[p.strip() for p in raw]
                rows.append(vals)
    return names, types, rows

def simple_jq(data, expr):
    if not expr:
        return data
    expr=expr.strip()
    if not expr:
        return data
    if expr.startswith('.'):
        expr=expr[1:]
    if not expr:
        return data
    parts=expr.split('.')
    cur=data
    for part in parts:
        if not part:
            continue
        if part.endswith('[]'):
            field=part[:-2]
            if field:
                if isinstance(cur, dict):
                    cur=cur.get(field)
                elif isinstance(cur, list):
                    new=[]
                    for el in cur:
                        if isinstance(el, dict):
                            v=el.get(field)
                            if v is not None:
                                new.append(v)
                    if new and isinstance(new[0], list):
                        flat=[]
                        for sub in new:
                            if isinstance(sub, list):
                                flat.extend(sub)
                            else:
                                flat.append(sub)
                        cur=flat
                    else:
                        cur=new
                else:
                    cur=None
            continue
        else:
            if part=="[]":
                continue
            if isinstance(cur, list):
                new_list=[]
                for el in cur:
                    if isinstance(el, dict):
                        new_list.append(el.get(part))
                    else:
                        new_list.append(None)
                cur=new_list
            elif isinstance(cur, dict):
                cur=cur.get(part)
            else:
                cur=None
        if cur is None:
            break
    return cur

def read_input_file(original_identifier, input_opts):
    file_part = original_identifier.split('::')[0] if '::' in original_identifier else original_identifier
    jq_from_table = original_identifier.split('::',1)[1] if '::' in original_identifier else None
    effective_jq = jq_from_table if jq_from_table is not None else input_opts.get('ijq')
    fmt_override = input_opts.get('format_override')
    fmt = fmt_override if fmt_override else guess_input_format(original_identifier)
    delim = input_opts.get('id')
    if delim is None:
        delim = '\t' if fmt=='tsv' else ','
    ih = input_opts.get('ih', False)
    inum = input_opts.get('inum', False)
    is_skip = input_opts.get('is', 0)
    ilr = input_opts.get('ilr', 0)
    inull = input_opts.get('inull', None)
    if file_part == '-':
        content = sys.stdin.read()
    else:
        if not os.path.exists(file_part):
            raise FileNotFoundError(file_part)
        with open(file_part, 'r', encoding='utf-8', newline='') as f:
            content=f.read()
    cols=[]
    rows=[]
    types=[]
    if fmt in ('csv','tsv'):
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        if not lines:
            return [], [], [], file_part, effective_jq
        reader=csv.reader(lines, delimiter=delim)
        all_rows=list(reader)
        if not all_rows:
            return [], [], [], file_part, effective_jq
        if ih:
            columns=all_rows[0]
            data_rows=all_rows[1:]
        else:
            max_cols=max(len(r) for r in all_rows) if all_rows else 0
            columns=[f'c{i+1}' for i in range(max_cols)]
            data_rows=all_rows
        if ilr and ilr>0:
            data_rows=data_rows[:ilr]
        result=[]
        idx=0
        for r in data_rows:
            idx+=1
            if len(r)<len(columns):
                r=r+['']*(len(columns)-len(r))
            elif len(r)>len(columns):
                r=r[:len(columns)]
            d={}
            for col,val in zip(columns, r):
                if inull is not None and val==inull:
                    d[col]=None
                else:
                    d[col]=val
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='ltsv':
        lines=content.splitlines()
        if is_skip:
            lines=lines[is_skip:]
        first=None
        for line in lines:
            if line.strip():
                first=line
                break
        if first is None:
            return [], [], [], file_part, effective_jq
        parts=first.split('\t')
        columns=[]
        for p in parts:
            if ':' in p:
                k=p.split(':',1)[0]
                if k and k not in columns:
                    columns.append(k)
        result=[]
        idx=0
        for line in lines:
            if not line.strip():
                continue
            idx+=1
            if ilr and idx>ilr:
                break
            mapping={}
            for field in line.split('\t'):
                if ':' not in field:
                    continue
                k,v=field.split(':',1)
                mapping[k]=v
            d={}
            for col in columns:
                v=mapping.get(col,'')
                if inull is not None and v==inull:
                    d[col]=None
                else:
                    d[col]=v
            if inum:
                d={'num': idx, **d}
            result.append(d)
        if inum:
            columns=['num']+columns
        cols=columns
        rows=result
        types=['text']*len(cols)
    elif fmt=='json':
        data=None
        if not content.strip():
            data=[]
        else:
            try:
                data=json.loads(content)
            except:
                items=[]
                for line in content.splitlines():
                    line=line.strip()
                    if not line:
                        continue
                    try:
                        items.append(json.loads(line))
                    except:
                        continue
                data=items
        if effective_jq:
            data=simple_jq(data, effective_jq)
        if isinstance(data, dict):
            list_data=[data]
        elif isinstance(data, list):
            list_data=data
        else:
            list_data=[]
        all_keys=[]
        for item in list_data:
            if isinstance(item, dict):
                for k in item.keys():
                    if k not in all_keys:
                        all_keys.append(k)
        columns=all_keys
        if is_skip:
            list_data=list_data[is_skip:]
