    "dblist": False,
    "debug": False,
    "help": False,
    "version": False,
    "icsv": False,
    "ig": False,
    "ijson": False,
    "iltsv": False,
    "itbln": False,
    "itext": False,
    "iwidth": False,
    "iyaml": False,
    "ih": False,
    "inum": False,
    "oat": False,
    "ocsv": False,
    "ojson": False,
    "ojsonl": False,
    "oltsv": False,
    "omd": False,
    "oraw": False,
    "otbln": False,
    "ovf": False,
    "oyaml": False,
    "oaq": False,
    "ocrlf": False,
    "oh": False,
    "onowrap": False,
    "out-without-guess": False,
    "h": False,
}
STRING_FLAGS = {
    "A": None,
    "a": None,
    "config": None,
    "db": None,
    "driver": None,
    "dsn": None,
    "q": None,
    "t": None,
